"""Explain waitqueue observations, ordering and exclusive quota."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1453': ('준비 담당자가 빈 명단을 보고 아무도 부르지 않았는데, 기다리는 사람도 예전 준비 표시만 보고 잠들면 어떻게 될까요? 준비가 끝나도 연락을 놓칠 수 있습니다.', '잠금 없는 대기열 조회에 접근 순서 규칙이 필요한 이유를 배웁니다.', '깨우는 쪽: 조건 참 기록 → 배리어 → 명단 확인 → 필요하면 깨움. 기다리는 쪽: 등록·대기 상태 설정 → 조건 확인 → 필요하면 잠들기를 나란히 적으세요.', ['waitqueue_active는 대기열 목록이 비어 있지 않은지 묻습니다. 본문은 !list_empty(&wq_head->head)입니다. list_empty가 빈 목록이면 참을 주고, !가 결과를 뒤집어 항목이 있으면 참으로 만듭니다.', '이 함수 안에는 spinlock을 잡는 코드가 없습니다. 따라서 호출했다는 이유로 다른 CPU가 목록을 바꾸지 못하게 되는 것은 아닙니다. 조회 직후 목록이 달라질 수 있고, 반환값이 태스크 소유권을 주지도 않습니다.', '깨우는 쪽은 조건을 바꾼 뒤 대기자가 없으면 wake 호출을 생략하고 싶을 수 있습니다. 하지만 CPU와 컴파일러가 메모리 접근 순서를 다루는 방식 때문에, 코드 줄만 앞에 썼다고 상대 CPU가 그 순서대로 봤다고 단정할 수 없습니다.', '원문은 대기열 잠금을 잡고 조회하거나, 잠금 없는 깨우기 판단에는 필요한 smp_mb 배리어를 두는 규약을 설명합니다. 배리어는 잠깐 쉬는 기능이 아니라 접근 순서를 맞추는 장치입니다. 기다리는 쪽의 상태 설정에 포함된 배리어와 짝을 이룹니다.', '규약이 없으면 깨우는 쪽은 예전의 빈 목록을 보고 호출을 생략하고, 기다리는 쪽은 예전의 거짓 조건을 보아 잠들 수 있습니다. 각자 보기에는 기다릴 이유와 부르지 않을 이유가 있지만 전체로는 필요한 연락을 놓친 것입니다.', '그래서 단순 조회처럼 보여도 사용 문맥을 함께 읽어야 합니다. 원문은 잠금을 배리어로 바꾸는 최적화의 비용도 고려하라고 설명합니다. 조회 하나가 더 싸 보인다고 배리어를 없애거나 객체가 계속 살아 있다는 보장으로 쓰면 안 됩니다.'], [('waitqueue_active가 내부에서 대기열 잠금을 잡을까요?', ['네. 인터럽트 상태까지 저장하고 잠가요', '아니요. 목록이 비었는지만 조회해요'], '본문은 !list_empty를 반환할 뿐입니다. 잠금과 순서 규약은 호출하는 쪽에서 마련해야 하므로 이 조회를 잠금 획득으로 읽으면 안 됩니다.'), ('잠금 없는 깨우기 판단에서 필요한 배리어를 생략해도 항상 안전할까요?', ['아니요. 양쪽이 서로의 새 기록을 놓칠 수 있어요', '네. 목록 조회만으로 모든 접근 순서가 맞아요'], '깨우는 쪽은 빈 명단을, 기다리는 쪽은 이전 조건을 관측할 위험이 있습니다. 조회 자체에 모든 순서 보장이 들어 있지 않으므로 필요한 배리어를 지켜야 합니다.')]), 'os1454': ('명단에 한 명이 적혀 있다는 사실과 그 사람이 지금 잠들어 있다는 사실은 다릅니다. 명단을 살펴보는 일과 실제로 사람을 부르는 일도 다릅니다.', '대기 항목 수 조회와 배리어를 포함한 존재 조회를 구별합니다.', '항목 수 0·1·2에 대해 single은 거짓·참·거짓, active는 거짓·참·참을 적으세요. 실제 수면 상태는 이 표만으로 모른다고 덧붙이세요.', ['wq_has_single_sleeper는 list_is_singular로 목록에 항목이 딱 하나인지 봅니다. singular는 하나라는 뜻입니다. 이름에 sleeper가 있어도 코드가 검사하는 대상은 태스크의 현재 수면 상태가 아니라 목록 구조입니다.', '항목이 없으면 거짓, 한 개면 참, 두 개면 거짓입니다. 참을 받았다고 목록의 잠금을 얻거나 항목을 마음대로 바꿀 권한을 받는 것은 아닙니다. 이 함수도 waitqueue_active 주석의 사용 조건을 따릅니다.', 'wq_has_sleeper는 먼저 smp_mb를 실행한 뒤 waitqueue_active를 부릅니다. smp_mb는 CPU 사이의 접근 순서를 맞추는 메모리 배리어입니다. 기다리는 쪽의 배리어와 짝을 이루어 등록 변화와의 순서를 맞추도록 돕습니다.', '이 함수는 항목이 있는지 확인할 뿐 wake_up을 호출하지 않습니다. 명단에 사람이 있는지 확인했다고 그 사람을 이미 불렀다고 말할 수 없는 것과 같습니다. 필요한 깨우기는 별도 호출 흐름에서 수행합니다.', '배리어가 있다고 목록 변경에 대한 잠금까지 자동으로 생기지는 않습니다. 동시에 항목을 넣고 빼는 규칙, 조건 변경의 순서, 대기열 객체가 유효하게 살아 있는 기간을 함께 지켜야 합니다.', '따라서 세 질문을 나눠 읽으세요. active는 항목이 있는가, single은 딱 하나인가, has_sleeper는 배리어를 거쳐 항목이 있는가입니다. 어느 조회도 작업이 반드시 지금 잠들었다거나 앞으로 목록이 변하지 않는다고 보장하지 않습니다.'], [('wq_has_sleeper가 active 조회 전에 실행하는 것은?', ['모든 대기자를 강제로 깨워요', 'smp_mb 메모리 배리어를 실행해요'], '본문은 smp_mb 뒤에 waitqueue_active를 반환합니다. 깨우기 함수를 호출하지 않으므로 조회만으로 모든 대기자가 깨어난다는 답은 틀립니다.'), ('single_sleeper가 참이면 잠금도 얻은 것일까요?', ['아니요. 목록에 항목이 하나인지 관측한 것이에요', '네. 참이라는 값이 spinlock 획득이에요'], 'list_is_singular는 항목 수에 관한 검사입니다. 잠금 획득도 아니고 태스크가 지금 자는지에 대한 직접 검사도 아닙니다.')]), 'os1455': ('우선 접수 카드들이 앞에 있고 일반 카드들이 뒤에 있습니다. 새 일반 카드는 우선 카드들 바로 뒤에 끼웁니다. 그래서 일반 카드끼리는 먼저 온 순서가 뒤집힐 수도 있습니다.', '내부 등록 함수가 우선 구간 뒤에 항목을 넣는 순서를 이해합니다.', 'P1,P2,A에서 일반 B를 넣으면 P1,P2,B,A, 다시 C를 넣으면 P1,P2,C,B,A를 쓰세요. P는 우선 표시가 있는 항목입니다.', ['__add_wait_queue는 대기 항목을 목록에 연결하는 내부 함수입니다. 처음 head라는 지역 포인터를 목록의 기준점으로 둡니다. 이 head는 새 항목을 넣을 위치를 찾아가는 메모입니다.', 'list_for_each_entry로 맨 앞부터 기존 항목을 살핍니다. WQ_FLAG_PRIORITY 표시가 있는 동안 그 항목의 뒤로 삽입 위치를 옮깁니다. 처음으로 우선 표시가 없는 항목을 만나면 break로 탐색을 멈춥니다.', '그다음 list_add로 찾은 위치 바로 뒤에 새 항목을 넣습니다. 기존 맨 앞의 연속된 우선 구간은 유지하고, 그 뒤 일반 구간의 앞쪽에 넣는 방식입니다. 우선 항목이 하나도 없으면 기준점 바로 뒤, 즉 목록의 맨 앞입니다.', '예를 들어 P1,P2,A에서 B를 넣으면 P1,P2,B,A입니다. 다시 C를 넣으면 P1,P2,C,B,A입니다. FIFO는 먼저 들어온 것이 먼저 나오는 규칙인데, 이 삽입 방식만으로 일반 항목 전체에 FIFO가 보장되지는 않습니다.', '이 내부 함수는 스스로 잠금을 잡지 않습니다. 보통 add_wait_queue 같은 바깥 함수가 인터럽트 상태를 저장하고 대기열 잠금을 잡은 다음 이 함수를 호출합니다. 이름의 밑줄 자체가 잠금을 만들어 주는 것은 아닙니다.', '우선 표시는 이 대기열에서의 배치 규칙입니다. CPU 스케줄러가 실행할 태스크의 우선순위와 무조건 같은 의미로 읽지 마세요. 또한 이 위치와 EXCLUSIVE의 깨우기 한도 규칙은 별개의 요소이므로 실제 깨우기 흐름까지 함께 확인합니다.'], [('이 내부 함수로 일반 항목을 넣으면 항상 목록 맨 뒤일까요?', ['네. 모든 항목이 반드시 먼저 온 순서를 지켜요', '아니요. 앞의 연속된 우선 항목들 바로 뒤에 넣어요'], '루프가 우선 항목들을 지난 위치를 고르고 list_add가 그 뒤에 삽입합니다. 맨 뒤에 넣는 list_add_tail과 다르므로 모든 일반 항목에 FIFO를 약속할 수 없습니다.'), ('__add_wait_queue가 스스로 잠금을 잡을까요?', ['아니요. 호출하는 쪽에서 보호해야 해요', '네. 이름에 밑줄이 있으면 자동으로 잠가요'], '본문은 위치 탐색과 목록 삽입입니다. 바깥 API가 잠금을 잡는 흐름을 확인해야 하며 이름의 밑줄은 실행 동작을 대신하지 않습니다.')]), 'os1456': ('한 번에 특별 입장권 한 장만 처리한다고 해 봅시다. 입장권 표시는 이번에 몇 명을 부를지 정하는 규칙입니다. 그 표시가 방 안 물건까지 자동으로 잠그지는 않습니다.', 'EXCLUSIVE 표시의 깨우기 한도와 목록 뒤 등록을 배웁니다.', 'P,A 목록 뒤에 exclusive E를 넣어 P,A,E를 그리세요. 별도로 일반 N은 우선 P 뒤에 들어 P,N,A,E가 된다고 적으세요.', ['add_wait_queue_exclusive는 먼저 항목 flags에 WQ_FLAG_EXCLUSIVE를 켭니다. |=는 기존 다른 표시를 남겨 두고 해당 비트 표시를 더하는 연산입니다. 항목을 쓰기 전에 올바르게 초기화해야 합니다.', '이어서 spin_lock_irqsave로 인터럽트 상태를 저장하고 대기열 잠금을 잡습니다. __add_wait_queue_entry_tail로 맨 뒤에 연결한 다음 잠금을 풀고 인터럽트 상태를 복원합니다. 여기서 tail은 끝이라는 뜻입니다.', '일반 add_wait_queue는 EXCLUSIVE 표시를 지우고 __add_wait_queue를 사용합니다. 이 helper는 앞의 우선 구간 뒤에 삽입합니다. add_wait_queue_priority는 EXCLUSIVE와 PRIORITY를 함께 켠 뒤 같은 helper로 우선 구간을 이어 갑니다.', 'EXCLUSIVE는 깨우기 순회에서 한도를 소비하는 표시입니다. 일반적인 깨우기 한도 1의 경우, 해당 표시가 있는 콜백이 양수를 반환하면 한도를 하나 줄이고 0이 되었을 때 멈춥니다. 콜백 반환과 표시를 함께 봐야 합니다.', '표시 없는 항목은 깨워도 이 exclusive 한도를 줄이지 않습니다. 따라서 한도 1이라고 모든 경우에 전체 태스크 딱 한 명만 깨우는 것은 아닙니다. 앞선 일반 항목들이 처리될 수도 있고, 맨 앞 우선 항목이 한도를 소모해 뒤까지 가지 않을 수도 있습니다.', 'EXCLUSIVE는 공유 자료를 고칠 때 쓰는 mutex가 아닙니다. 데이터의 동시 수정과 조건 소비는 호출자 규약으로 따로 보호합니다. 또한 이미 목록에 연결된 같은 entry를 다시 삽입하면 연결을 망가뜨릴 수 있으므로 한 항목의 등록·제거 상태를 지켜야 합니다.'], [('add_wait_queue_exclusive는 새 항목을 어디에 넣을까요?', ['언제나 모든 우선 항목보다 앞으로 넣어요', '목록 맨 뒤에 넣어요'], '이 바깥 API는 __add_wait_queue_entry_tail을 사용합니다. 우선 구간 뒤의 앞쪽을 고르는 일반 helper와 이름이 비슷해도 호출하는 삽입 함수가 다릅니다.'), ('EXCLUSIVE 표시만 있으면 공유 조건 데이터의 동시 수정도 막을까요?', ['아니요. 이 표시는 깨우기 순회의 한도 규칙이에요', '네. 조건 데이터를 자동으로 잠그는 mutex예요'], '콜백 결과에 따라 깨우기 한도를 소비할지 정하는 표시입니다. 데이터 보호 잠금을 획득하는 동작이 아니므로 실제 조건 변경과 소비는 별도 규약을 지켜야 합니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_359.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
